"""Incident report generation (JSON + Markdown) strictly from stored evidence."""

from __future__ import annotations

import math
from datetime import UTC, datetime
from typing import Any

from app.repositories.sql import Repository

NOTICE = (
    "SIMULATED DATA - This report was generated by OT Sentinel Twin from a fully synthetic digital twin. "
    "It does not describe real equipment, a real facility or a real security event."
)
LABELS = {
    "data_quality": "Data-quality issue",
    "equipment_fault": "Equipment fault",
    "physical_anomaly": "Physical process anomaly",
    "suspected_manipulation": "Suspected security-related manipulation",
}
SIGNALS = {
    "lt101": ("LT-101 primary level", "m"),
    "lt102": ("LT-102 secondary level", "m"),
    "ft101": ("FT-101 inlet flow", "L/s"),
    "ft102": ("FT-102 outlet flow", "L/s"),
    "pt101": ("PT-101 line pressure", "bar"),
    "zt101": ("ZT-101 inlet valve position", "%"),
    "zt102": ("ZT-102 outlet valve position", "%"),
    "inlet_cmd": ("XV-101 inlet valve command", "%"),
    "residual_lt101": ("Mass-balance residual (LT-101)", "m3"),
    "residual_lt102": ("Mass-balance residual (LT-102)", "m3"),
    "disagreement": ("LT-101 minus LT-102", "m"),
}
LIMITATIONS = [
    "The plant model is a simplified, documented digital twin; thresholds are calibrated to its synthetic "
    "noise model and are not transferable to real equipment without re-validation.",
    "Detection is limited to the instrumented signals. Simultaneous, mutually consistent falsification of "
    "redundant instruments and flow meters could evade physics-consistency checks.",
    "Classification is a rule-based hypothesis derived from telemetry patterns; it is not an attribution and "
    "does not prove malicious intent.",
    "Simulator ground truth (if shown) was not available to the detection engine and is included only to "
    "support evaluation of this demonstration.",
]


def _stats(values: list[Any]) -> dict[str, float] | None:
    xs = [
        float(v)
        for v in values
        if isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)
    ]
    if not xs:
        return None
    return {"min": round(min(xs), 4), "max": round(max(xs), 4), "mean": round(sum(xs) / len(xs), 4)}


def build_report(repo: Repository, incident_id: str) -> dict[str, Any] | None:
    inc = repo.get_incident(incident_id)
    if inc is None:
        return None
    run = repo.get_run(inc["run_id"]) or {}
    assets = {a["id"]: a for a in repo.list_assets()}
    detections = inc["detections"]
    t0 = float(inc["first_seen_t"])
    t1 = float(inc["last_seen_t"])
    before = repo.samples_window(inc["run_id"], t0 - 60.0, t0)
    during = repo.samples_window(inc["run_id"], t0, t1 + 1e-6)
    telemetry = []
    for key, (label, unit) in SIGNALS.items():
        telemetry.append(
            {
                "signal": key,
                "label": label,
                "unit": unit,
                "before": _stats([r[key] for r in before]),
                "during": _stats([r[key] for r in during]),
            }
        )
    step = max(1, len(during) // 60)
    excerpt = [
        {
            "t": r["t"],
            "ts": r["ts"],
            **{
                k: r[k]
                for k in (
                    "lt101",
                    "lt102",
                    "ft101",
                    "ft102",
                    "pt101",
                    "zt101",
                    "inlet_cmd",
                    "residual_lt101",
                    "disagreement",
                )
            },
        }
        for r in during[::step]
    ]

    rules = []
    discrepancies = []
    for d in detections:
        rules.append(
            {
                k: d[k]
                for k in (
                    "id",
                    "rule_id",
                    "title",
                    "instance_key",
                    "asset_id",
                    "severity",
                    "category",
                    "status",
                    "first_seen",
                    "raised_at",
                    "cleared_at",
                    "observed_value",
                    "expected_value",
                    "threshold",
                    "units",
                    "peak_score",
                    "explanation",
                )
            }
        )
        peak = next((e for e in d["evidence"] if e.get("phase") == "peak"), None) or (
            d["evidence"][-1] if d["evidence"] else None
        )
        if peak:
            discrepancies.append(
                {
                    "rule_id": d["rule_id"],
                    "instance": d["instance_key"],
                    "at": peak.get("ts"),
                    "observed": peak.get("observed"),
                    "expected": peak.get("expected"),
                    "statistic": peak.get("statistic"),
                    "threshold": peak.get("threshold"),
                    "units": d["units"],
                    "values": peak.get("values", {}),
                }
            )
    rule_meta = {r["rule_id"]: r for r in _rule_descriptions(repo)}
    methodology = [rule_meta[r] for r in sorted({d["rule_id"] for d in detections}) if r in rule_meta]

    timeline: list[dict[str, Any]] = []
    for e in inc["timeline"]:
        timeline.append(
            {
                "ts": e.get("ts"),
                "t": e.get("t"),
                "source": "detection-engine",
                "type": e.get("type"),
                "text": e.get("text"),
            }
        )
    for n in inc["notes"]:
        timeline.append(
            {
                "ts": n["created_at"],
                "t": None,
                "source": f"analyst:{n['author']}",
                "type": "note",
                "text": n["text"],
            }
        )
    for a in inc["audit"]:
        timeline.append(
            {
                "ts": a["ts"],
                "t": None,
                "source": f"analyst:{a['actor']}",
                "type": a["action"],
                "text": f"{a['action']} {a.get('details') or ''}".strip(),
            }
        )

    ground_truth = [
        {
            "ts": e["ts"],
            "t": e["sim_time_s"],
            "kind": e["kind"],
            "scenario_id": e["scenario_id"],
            "description": e["description"],
        }
        for e in inc["scenario_events"]
        if t0 - 600 <= e["sim_time_s"] <= t1 + 600
    ]
    cls = inc["classification"]
    assets_list = [
        {"id": a, "name": assets.get(a, {}).get("name", a), "kind": assets.get(a, {}).get("kind", "")}
        for a in inc["assets"]
    ]
    duration = max(t1 - t0, 0.0)
    exec_summary = (
        f"Between {inc['first_seen']} and {inc['last_seen']} (simulated time, {duration:.0f} s) the detection engine "
        f"raised {len(detections)} detection(s) from {len({d['rule_id'] for d in detections})} rule(s) affecting "
        f"{', '.join(a['id'] for a in assets_list)}. The incident is classified as '{LABELS.get(cls, cls)}' with "
        f"{inc['confidence']} confidence. {inc['summary']}"
    )
    conclusions = (
        f"Stored telemetry shows a measurable inconsistency between reported values and the documented process "
        f"model ({', '.join(sorted({d['rule_id'] for d in detections}))}). "
        + (
            "The evidence pattern matches deceptive manipulation of a control input, but non-malicious causes "
            "listed above remain possible and must be ruled out by field verification. "
            if cls == "suspected_manipulation"
            else "The evidence does not by itself indicate malicious activity. "
        )
        + f"Current analyst status: {inc['status']}. No remediation results are recorded in this report."
    )
    return {
        "report_id": f"RPT-{incident_id}",
        "generated_at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
        "data_notice": NOTICE,
        "executive_summary": exec_summary,
        "simulation": {
            k: run.get(k)
            for k in (
                "id",
                "epoch",
                "seed",
                "mode",
                "status",
                "started_at",
                "sample_interval_s",
                "sim_duration_s",
            )
        },
        "incident": {
            k: inc[k]
            for k in (
                "id",
                "title",
                "classification",
                "confidence",
                "severity",
                "status",
                "acknowledged",
                "detection_state",
                "first_seen",
                "last_seen",
            )
        },
        "classification_label": LABELS.get(cls, cls),
        "affected_assets": assets_list,
        "timeline": sorted(timeline, key=lambda x: x["ts"] or ""),
        "triggered_rules": rules,
        "discrepancies": discrepancies,
        "expected_behavior": inc["expected_behavior"],
        "observed_behavior": inc["observed_behavior"],
        "supporting_telemetry": {
            "window_s": [round(t0 - 60, 1), round(t1, 1)],
            "signals": telemetry,
            "excerpt": excerpt,
        },
        "methodology": methodology,
        "classification_basis": inc["classification_basis"],
        "confidence_rationale": inc["confidence_rationale"],
        "alternative_explanations": inc["alternatives"],
        "evidence_limitations": LIMITATIONS,
        "recommended_investigation_steps": inc["recommended_steps"],
        "analyst_notes": inc["notes"],
        "conclusions": conclusions,
        "simulator_ground_truth": {
            "notice": "Ground truth from the scenario laboratory. NOT available to the detection engine.",
            "events": ground_truth,
        },
    }


def _rule_descriptions(repo: Repository) -> list[dict[str, Any]]:
    from sqlalchemy import select

    from app.models.db import DetectionRule

    with repo.session() as s:
        return [
            {
                "rule_id": r.rule_id,
                "title": r.title,
                "description": r.description,
                "methodology": r.methodology,
                "config": r.config,
            }
            for r in s.scalars(select(DetectionRule))
        ]


def _fmt(v: Any, nd: int = 3) -> str:
    if v is None:
        return "-"
    if isinstance(v, float):
        return f"{v:.{nd}f}"
    return str(v)


def render_markdown(r: dict[str, Any]) -> str:
    inc = r["incident"]
    out: list[str] = []
    w = out.append
    w(f"# Incident Report {inc['id']}: {inc['title']}")
    w("")
    w(f"> **{r['data_notice']}**")
    w("")
    w(f"Report `{r['report_id']}` generated {r['generated_at']}")
    w("")
    w("## 1. Executive summary")
    w("")
    w(r["executive_summary"])
    w("")
    w("| Classification | Confidence | Severity | Analyst status | Detection state |")
    w("|---|---|---|---|---|")
    w(
        f"| {r['classification_label']} | {inc['confidence']} | {inc['severity']} | {inc['status']} | "
        f"{inc['detection_state']} |"
    )
    w("")
    sim = r["simulation"]
    w("## 2. Simulation identification")
    w("")
    w(
        f"- Run: `{sim.get('id')}` (mode {sim.get('mode')}, seed {sim.get('seed')}, scan "
        f"{sim.get('sample_interval_s')} s)"
    )
    w(f"- Simulated epoch: {sim.get('epoch')}; run started {sim.get('started_at')}")
    w("")
    w("## 3. Affected simulated assets")
    w("")
    for a in r["affected_assets"]:
        w(f"- **{a['id']}** - {a['name']} ({a['kind']})")
    w("")
    w("## 4. Incident timeline")
    w("")
    w("| Time (sim) | Source | Event |")
    w("|---|---|---|")
    for e in r["timeline"]:
        w(f"| {e['ts']} | {e['source']} | {str(e['text']).replace('|', '/')} |")
    w("")
    w("## 5. Triggered detection rules")
    w("")
    w("| Detection | Rule | Instance | Severity | Raised | Cleared | Observed | Expected | Threshold |")
    w("|---|---|---|---|---|---|---|---|---|")
    for d in r["triggered_rules"]:
        w(
            f"| {d['id']} | {d['rule_id']} {d['title']} | {d['instance_key']} | {d['severity']} | {d['raised_at']} | "
            f"{d['cleared_at'] or 'active'} | {_fmt(d['observed_value'])} {d['units']} | "
            f"{_fmt(d['expected_value'])} {d['units']} | {_fmt(d['threshold'])} {d['units']} |"
        )
    w("")
    w("## 6. Physical process discrepancies")
    w("")
    w(f"- Expected: {r['expected_behavior']}")
    w(f"- Observed: {r['observed_behavior']}")
    for d in r["triggered_rules"]:
        w(f"- **{d['rule_id']} / {d['instance_key']}**: {d['explanation']}")
    w("")
    w("## 7. Supporting telemetry")
    w("")
    win = r["supporting_telemetry"]["window_s"]
    w(f"Statistics 60 s before onset vs. during the incident (sim time {win[0]} s - {win[1]} s).")
    w("")
    w("| Signal | Unit | Before (min / mean / max) | During (min / mean / max) |")
    w("|---|---|---|---|")
    for s in r["supporting_telemetry"]["signals"]:
        b, d_ = s["before"], s["during"]
        bs = "-" if not b else f"{b['min']} / {b['mean']} / {b['max']}"
        ds = "-" if not d_ else f"{d_['min']} / {d_['mean']} / {d_['max']}"
        w(f"| {s['label']} | {s['unit']} | {bs} | {ds} |")
    w("")
    w("## 8. Detection methodology")
    w("")
    for m in r["methodology"]:
        cfg = m["config"]
        w(
            f"- **{m['rule_id']} {m['title']}** - {m['description']} *Method:* {m['methodology']} "
            f"(threshold {cfg.get('threshold')} {cfg.get('units')}, debounce {cfg.get('debounce_s')} s, "
            f"clear after {cfg.get('clear_s')} s)"
        )
    w("")
    w("## 9. Evidence and limitations")
    w("")
    w("**Classification basis:**")
    for b in r["classification_basis"]:
        w(f"- {b}")
    w(f"\n**Confidence:** {inc['confidence']} - {r['confidence_rationale']}")
    w("\n**Possible non-malicious explanations:**")
    for a in r["alternative_explanations"]:
        w(f"- {a}")
    w("\n**Limitations:**")
    for lim in r["evidence_limitations"]:
        w(f"- {lim}")
    w("")
    w("## 10. Recommended investigation steps")
    w("")
    for i, s in enumerate(r["recommended_investigation_steps"], 1):
        w(f"{i}. {s}")
    if r["analyst_notes"]:
        w("\n**Analyst notes:**")
        for n in r["analyst_notes"]:
            w(f"- {n['created_at']} {n['author']}: {n['text']}")
    w("")
    w("## 11. Conclusions")
    w("")
    w(r["conclusions"])
    w("")
    gt = r["simulator_ground_truth"]
    if gt["events"]:
        w("---")
        w("")
        w(f"*Appendix - {gt['notice']}*")
        w("")
        for e in gt["events"]:
            w(f"- {e['ts']} `{e['kind']}` {e['scenario_id']}: {e['description']}")
        w("")
    return "\n".join(out)
